changeSet.sql:
INSERT INTO sub_modules (name, code, module_id, enabled)
SELECT 'Inventario', 'INVENTORY', (SELECT id FROM modules WHERE code = 'GENERAL'), 1
WHERE NOT EXISTS (SELECT 1 FROM sub_modules WHERE code = 'INVENTORY');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ver inventario', 'inventory.read', (SELECT id FROM sub_modules WHERE code = 'INVENTORY'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'inventory.read');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Ajustar inventario', 'inventory.adjust', (SELECT id FROM sub_modules WHERE code = 'INVENTORY'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'inventory.adjust');

INSERT INTO base_permissions (name, code, sub_module_id, enabled)
SELECT 'Transferir inventario', 'inventory.transfer', (SELECT id FROM sub_modules WHERE code = 'INVENTORY'), 1
WHERE NOT EXISTS (SELECT 1 FROM base_permissions WHERE code = 'inventory.transfer');
